//! Wire types shared with the frontend ("Meeting mode" contract).
//!
//! Names and shapes are part of the contract with `src/` and must stay in
//! sync with the TypeScript bindings generated by specta.

use serde::{Deserialize, Serialize};
use specta::Type;

/// Which capture track a speaker/segment belongs to.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq, Type)]
#[serde(rename_all = "snake_case")]
pub enum MeetingSource {
    /// The user's microphone.
    Microphone,
    /// System playback captured through WASAPI loopback.
    System,
}

impl MeetingSource {
    /// Stable string used in SQLite rows.
    pub fn as_db_str(self) -> &'static str {
        match self {
            MeetingSource::Microphone => "microphone",
            MeetingSource::System => "system",
        }
    }

    /// Inverse of [`MeetingSource::as_db_str`]; unknown values map to the microphone.
    pub fn from_db_str(value: &str) -> Self {
        if value == "system" {
            MeetingSource::System
        } else {
            MeetingSource::Microphone
        }
    }

    /// Default (untranslated) speaker label for this source.
    pub fn default_label(self) -> &'static str {
        match self {
            MeetingSource::Microphone => "Я",
            MeetingSource::System => "Собеседник",
        }
    }

    /// File-name prefix used for the 30-second WAV chunks.
    pub fn file_prefix(self) -> &'static str {
        match self {
            MeetingSource::Microphone => "mic",
            MeetingSource::System => "sys",
        }
    }
}

/// Which sources a meeting records.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq, Type)]
pub struct MeetingSources {
    pub microphone: bool,
    pub system_audio: bool,
}

/// Live state machine of the meeting recorder.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq, Type)]
#[serde(rename_all = "snake_case")]
pub enum MeetingState {
    Idle,
    Recording,
    Paused,
    Finalizing,
}

/// Persisted status of a meeting row.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq, Type)]
#[serde(rename_all = "snake_case")]
pub enum MeetingRecordStatus {
    Recording,
    Completed,
    /// The app exited (or crashed) while this meeting was still recording.
    Interrupted,
}

impl MeetingRecordStatus {
    /// Stable string used in SQLite rows.
    pub fn as_db_str(self) -> &'static str {
        match self {
            MeetingRecordStatus::Recording => "recording",
            MeetingRecordStatus::Completed => "completed",
            MeetingRecordStatus::Interrupted => "interrupted",
        }
    }

    /// Inverse of [`MeetingRecordStatus::as_db_str`]; unknown values map to `Interrupted`.
    pub fn from_db_str(value: &str) -> Self {
        match value {
            "recording" => MeetingRecordStatus::Recording,
            "completed" => MeetingRecordStatus::Completed,
            _ => MeetingRecordStatus::Interrupted,
        }
    }
}

/// Snapshot emitted as `meeting-status` and returned by `meeting_status`.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Type)]
pub struct MeetingStatus {
    pub state: MeetingState,
    pub meeting_id: Option<i64>,
    /// Recorded time excluding pauses.
    pub elapsed_ms: u64,
    /// 0.0..=1.0 microphone meter.
    pub mic_level: f32,
    /// 0.0..=1.0 system-audio meter.
    pub system_level: f32,
    pub segment_count: u32,
    pub last_error: Option<String>,
}

/// Summary row of a meeting.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Type)]
pub struct MeetingInfo {
    pub id: i64,
    pub title: String,
    /// Unix milliseconds.
    pub started_at: i64,
    /// Unix milliseconds.
    pub ended_at: Option<i64>,
    pub duration_ms: u64,
    pub sources: MeetingSources,
    pub segment_count: u32,
    pub speaker_count: u32,
    pub status: MeetingRecordStatus,
    pub summary: Option<String>,
}

/// One speaker slot of a meeting (one per source in the MVP).
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Type)]
pub struct MeetingSpeaker {
    pub id: i64,
    pub meeting_id: i64,
    pub slot: i32,
    pub source: MeetingSource,
    pub label: String,
    pub name: Option<String>,
    pub color_index: i32,
}

/// One transcript segment. `is_final == false` means the text is still being produced.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Type)]
pub struct MeetingSegment {
    pub id: i64,
    pub meeting_id: i64,
    pub t0_ms: u64,
    pub t1_ms: u64,
    pub speaker_id: Option<i64>,
    pub source: MeetingSource,
    pub text: String,
    pub is_final: bool,
}

/// Full meeting payload returned by `meeting_get`.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Type)]
pub struct MeetingDetail {
    pub info: MeetingInfo,
    pub speakers: Vec<MeetingSpeaker>,
    pub segments: Vec<MeetingSegment>,
}

/// Export formats supported by `meeting_export`.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq, Type)]
#[serde(rename_all = "snake_case")]
pub enum MeetingExportFormat {
    Txt,
    Md,
    Json,
    Srt,
}

impl MeetingExportFormat {
    /// File extension (without the dot).
    pub fn extension(self) -> &'static str {
        match self {
            MeetingExportFormat::Txt => "txt",
            MeetingExportFormat::Md => "md",
            MeetingExportFormat::Json => "json",
            MeetingExportFormat::Srt => "srt",
        }
    }
}

/// Payload of the `meeting-error` event.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Type)]
pub struct MeetingErrorPayload {
    pub message: String,
}
